a := [1,2,3]
fn(shrink()) { a = [9] }
for (x : a) { shrink(); print(x) }
print("done")

a := [1,2,3]
fn(h()) { return g() }
fn(g()) { a = [9]
  return 0 }
for (x : a) { h(); print(x) }
print("done")

a := [1,2,3]
f := () => 0
i := 0
while (i < 2) {
  i += 1
  for (x : a) { f(); print(x) }
  f = () => { a = [9]
    return 0 }
}
print("done")

a := [1,2,3]
s := () => { a = [9]
  return 0 }
for (x : a) { s(); print(x) }
print("done")

fn(runit()) {
  a := [1,2,3]
  s := () => { a = [9]
    return 0 }
  for (x : a) { s(); print(x) }
  return 0
}
print(runit())

a := [1,2,3]
for (x : a) { a = a.slice(0, 1); print(x) }
print("done")

a := [1,2,3]
fn(f()) {
  for (x : a) { a = [9]; print(x) }
  return 0
}
print(f())

a := [1,2,3]
fn(f()) {
  for (x : a) { a[1] = 99; print(x) }
  return 0
}
print(f())

a := [1,2,3]
for (x : a) { for (y : a) { print(y) }; a = [9]; print(x) }
print("done")

o := {"a":1,"b":2,"c":3}
fn(drop()) { o = {"a":1} }
for ((k,v) : o) { drop(); print(k); print(v) }
print("done")

a := [1,2,3]
for (x : a) { j := 0
  while (j < 1) { a = [9]; j += 1 }
  print(x) }
print("done")

o := {"a":1,"b":2,"c":3}
s := () => { o = {"a":1}
  return 0 }
for ((k,v) : o) { s(); print(k); print(v) }
print("done")

a := [1,2,3]
fn(setit()) { a[1] = 50 }
for (x : a) { setit(); print(x) }
print("done")

o := {"a":1,"b":2}
fn(reset()) { o = {"a":5,"b":6} }
for ((k,v) : o) { reset(); print(v) }
print("done")

a := [1,2]
fn(reset()) { a = [5,6] }
for (x : a) { reset(); print(x) }
print("done")

a := [1,2,3]
fn(shrink()) { a = [9] }
for (x : a) { print("s"); shrink(); print(x) }
print("done")

a := [1,2,3]
s := () => { a = [9] }
for (x : a) { s(); print(x) }
print("done")

a := [1,2,3]
for (x : a) { a.pop(); print(x) }
print("done")

a := [1,2,3,4]
for (x : a) { print(x); a.pop() }
print("done")

a := [1,2,3]
for (x : a) { for (y : a) { a = [9] }; print(x) }
print("done")

a := [1,2,3]
for (x : a) { a = [9]; print("s"); if (true) { print(x) } }
print("done")
